import unittest,re
from tools.kjv_archive import load_register,read
class HebrewsGatheredVoicesTests(unittest.TestCase):
 def test_gathered_voices_and_closing_exhortation(self):
  prior,_=load_register('0.10-kjv.262');lang,manifest=load_register('0.10-kjv.263')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('hebrews-'):c for c in read(lang.folder/'hebrews-gathered-voices-cases.json')};self.assertEqual(len(cases),54)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}&set(r['keys']))
  anchors={'12:1': ['wesg also', 'witness:pl cloud', 'every weight and sin', 'easily entangle', 'patience kjv_race'], '12:2': ['ourone/faith begin:ag and finish:ag', 'joy which before he', 'kjv_cross_instrument', 'god throne kjv_right_side'], '12:3': ['against himself sin:ag:pl', 'kjv_gainsay_romans:ev', 'your/mind:pl weary and faint'], '12:4': ['against sin strive', 'to blood not yet resistance'], '12:5': ['you kjv_exhort_romans:ev', 'as to child:pl', 'my/son thou', 'kjv_chasten:ev despise:neg', 'rebuke:psv'], '12:6': ['whom lord love', 'every son', 'whip'], '12:7': ['if you', 'as with son:pl', 'what son', 'kjv_chasten:neg:pr'], '12:8': ['without kjv_chasten:ev', 'all share:ag:pl', 'bastard:pl and not son:pl'], '12:9': ['wesg ourone/flesh father:pl', 'honour give', 'spirit:pl father', 'submit:neg:fu:q'], '12:10': ['few day:pl', 'their/own pleasure', 'ourone/benefit', 'his/holy:ev share'], '12:11': ['for present joy:adj', 'pain:adj', 'afterward', 'kjv_exercise_training_timothy:psv', 'peace:adj fruit'], '12:12': ['hand:pl which down hang', 'feeble knee:pl'], '12:13': ['your/foot:pl straight path:pl', 'kjv_lame', 'out of way', 'rather it heal:psv'], '12:14': ['all man:pl peace', 'holy:ev without which no man'], '12:15': ['of god grace fail', 'bitter:ev root', 'many defile:psv'], '12:16': ['kjv_fornication:ag or kjv_profane:ag', 'kjv_esau', 'one_num kjv_morsel of food', 'birthright sell'], '12:17': ['blessing inherit:inf will:pa', 'reject:psv', 'kjv_repentance_turn_hebrews place no', 'carefully with tear:pl'], '12:18': ['mountain which touch:psv:can', 'black:ev and darkness and tempest', 'come:neg:perf'], '12:19': ['trumpet sound', 'word:pl voice', 'any more speak:psv:neg'], '12:20': ['endure:neg:can', 'even beast', 'stone:psv:fu or with kjv_dart'], '12:21': ['kjv_moses say', 'i greatly fear:pr and quake'], '12:22': ['kjv_sion_hebrews', 'alive god city heavenly kjv_jerusalem', 'angel:pl kjv_number:psv:neg:can:adj'], '12:23': ['whole kjv_assembly and kjv_church_assembly', 'kjv_firstborn_human:pl', 'in heaven write:psv', 'god all judge:ag', 'spirit:pl perfect'], '12:24': ['kjv_jesus_matthew new kjv_covenant kjv_mediator_timothy', 'kjv_sprinkle:ev blood', 'kjv_abel better'], '12:25': ['refuse:neg:pr', 'on earth', 'much more wesg', 'from heaven', 'escape:neg:fu'], '12:26': ['then earth shake', 'yet once more ipl', 'not earth only but also heaven'], '12:27': ['yet once more', 'remove:ev', 'make:psv:pp thing:pl', 'shake:psv:neg:can remain:may'], '12:28': ['wesg kingdom which move:psv:neg:can', 'wesg grace have:opt', 'honour and god:adj fear'], '12:29': ['ourone/god kjv_consume:cv fire'], '13:1': ['brother:adj love continue'], '13:2': ['stranger:pl entertain', 'some not know:cv angel:pl'], '13:3': ['chain:pl person:pl', 'as with they bind:psv', 'kjv_adversity', 'yourselves also in body'], '13:4': ['marriage in all', 'bed defile:psv:neg', 'kjv_fornication:ag:pl and kjv_adulterer:pl'], '13:5': ['kjv_conversation_conduct_corinthians without kjv_covetousness', 'content be:imp', 'ipl thou:a never leave:fu', 'forsake:fu'], '13:6': ['wesg bold:adv say:may', 'mypl/help:ag', 'ipl what man to ipl', 'fear:neg:fu'], '13:7': ['over you rule', 'god word speak', 'whose faith follow', 'conduct_corinthians end'], '13:8': ['kjv_jesus_matthew kjv_christ_title', 'kjv_yesterday and today and forever same'], '13:9': ['different and strange teach:ev:pl', 'carry:psv:neg:imp', 'heart with grace', 'not with food:pl', 'benefit give:neg'], '13:10': ['wesg altar have', 'kjv_tabernacle serve', 'eat:inf authority no'], '13:11': ['beast:pl body:pl', 'high priest for sin', 'kjv_sanctuary', 'outside camp burn'], '13:12': ['his/own blood people sanctify', 'outside gate suffer'], '13:13': ['wesg to he outside camp', 'his/kjv_reproach carry'], '13:14': ['wesg continue:cv city no have', 'wesg come:cv city seek'], '13:15': ['wesg to god praise kjv_sacrifice always', 'his/name thanks', 'ourone/lip:pl fruit'], '13:16': ['good do:inf', 'kjv_communicate_share_hebrews', 'god well kjv_please_satisfy'], '13:17': ['over you rule', 'your/kjv_soul:pl watch', 'reckon:ev give:must', 'joy and not with grief', 'benefit:neg:adj'], '13:18': ['for wesg pray', 'wesg good conscience', 'all thing:pl honestly live'], '13:19': ['i you:a', 'i to you sooner restore:psv:may'], '13:20': ['peace god', 'from dead:pl ourone/lord kjv_jesus_matthew', 'great sheep shepherd', 'eternal kjv_covenant blood'], '13:21': ['every good work his/will:ev', 'in you', 'through kjv_jesus_matthew kjv_christ_title', 'forever and forever'], '13:22': ['i you brother:pl', 'kjv_exhort_romans:ev word endure', 'i to you in few word:pl letter'], '13:23': ['ourone/brother kjv_timothy_second_corinthians', 'free set:psv', 'if he soon come', 'i you:a see'], '13:24': ['all they who over you rule', 'all saint:pl', 'they of italy'], '13:25': ['grace with you all', 'amen']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('ourone/faith begin:ag and finish:ag',cases['12-2']['analysis'])
  self.assertIn('if you kjv_chasten:ev endure:pr',cases['12-7']['analysis'])
  self.assertIn('kjv_repentance_turn_hebrews place no find:pa',cases['12-17']['analysis'])
  self.assertIn('kjv_moses say:pa i',cases['12-21']['analysis'])
  self.assertIn('yet once more ipl',cases['12-26']['analysis'])
  self.assertIn('ipl thou:a never leave:fu',cases['13-5']['analysis'])
  self.assertIn('wesg bold:adv say:may lord mypl/help:ag',cases['13-6']['analysis'])
  self.assertIn('kjv_communicate_share_hebrews:inf',cases['13-16']['analysis'])
  self.assertIn('in you',cases['13-21']['analysis'])
  self.assertIn('if he soon come:pr',cases['13-23']['analysis'])
  self.assertIn('they of italy',cases['13-24']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),3)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
